#include <cassert>
#include <cmath>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error "Tests require assertions enabled."
#endif
class Flick1D {
    bool seen_=false, armed_=false;
    double lastTime_=0.0, centerTime_=0.0;
public:
    // 반환: -1 왼쪽, 0 이벤트 없음, +1 오른쪽. 입력 시간 단위는 초다.
    int sample(double time, double x) {
        // 실패 입력은 상태를 바꾸기 전에 거부한다.
        if(!std::isfinite(time) || !std::isfinite(x) || time<0.0 ||
           time>1000000.0 || x < -1.0 || x > 1.0 ||
           (seen_ && time<=lastTime_)) throw std::invalid_argument("invalid sample");
        seen_=true; lastTime_=time;
        if(std::fabs(x)<=0.2) { armed_=true; centerTime_=time; return 0; }
        if(armed_ && std::fabs(x)>=0.8) {
            armed_=false; // 바깥 문턱에서는 성공 여부와 무관하게 한 번 소비한다.
            if(time-centerTime_<=0.08) return x>0.0 ? 1 : -1;
        }
        return 0;
    }
};
int main() {
    Flick1D fast;
    assert(fast.sample(0.0,0.0)==0);
    assert(fast.sample(0.04,0.9)==1);
    assert(fast.sample(0.05,1.0)==0); // 계속 기울여도 반복 발동하지 않는다.
    assert(fast.sample(0.06,0.0)==0);
    assert(fast.sample(0.10,-0.9)==-1); // 중립 복귀 후 재무장
    Flick1D slow;
    assert(slow.sample(0.0,0.0)==0);
    assert(slow.sample(0.04,0.25)==0);
    assert(slow.sample(0.08,0.5)==0);
    assert(slow.sample(0.12,0.75)==0);
    assert(slow.sample(0.16,0.9)==0);
    assert(slow.sample(0.17,1.0)==0);
    Flick1D edge;
    assert(edge.sample(0.0,0.2)==0);
    assert(edge.sample(0.08,0.8)==1); // 이중 문턱과 시간 경계 포함
    Flick1D outside;
    assert(outside.sample(0.0,1.0)==0); // 중립을 관찰하지 않았으면 발동 금지
    int rejected=0;
    try { fast.sample(0.09,0.0); } catch(const std::invalid_argument&) { ++rejected; }
    try { fast.sample(0.11,2.0); } catch(const std::invalid_argument&) { ++rejected; }
    try { fast.sample(0.11,std::nan("")); } catch(const std::invalid_argument&) { ++rejected; }
    assert(rejected==3);
    assert(fast.sample(0.11,0.0)==0); // 잘못된 표본은 시간을 소비하지 않았다.
    assert(fast.sample(0.15,0.9)==1);
    Flick1D noise;
    for(int k=0;k<1000;++k) assert(noise.sample(k*0.001,(k%2?0.19:-0.19))==0);
    std::cout<<"flick tests passed\n";
}
